'use client';

import { useEffect, useMemo, useState } from 'react';
import { adminEvents, adminPeople, apiRequest, deleteEvent, deletePerson, getAlumni, getEvents, logout, refreshSession, rsvp, updateProfile } from '../services/api';

const tabs = [
    ['Overview', '◒'],
    ['Alumni directory', '◌'],
    ['Events', '▣'],
    ['My profile', '◉']
];

function initials(name = '') { return name.split(' ').map((part) => part[0]).join('').slice(0, 2).toUpperCase(); }
function dateParts(value) { const date = new Date(value); return { month: date.toLocaleDateString('en', { month: 'short' }).toUpperCase(), day: date.getDate() }; }

function EventCard({ event, registered, onRsvp, onDelete, admin }) {
    const date = event.month ? event : dateParts(event.date);
    return <article className="event-card"><div className="date-tile"><span>{date.month}</span><strong>{date.day}</strong></div><div className="event-copy"><span className="tag">{event.type || 'COMMUNITY'}</span><h3>{event.title}</h3><p>{event.location || 'Location to be announced'}</p><div className="event-actions">{admin ? <button className="rsvp-button danger" onClick={() => onDelete(event.id)}>Delete</button> : <button className={registered ? 'rsvp-button registered' : 'rsvp-button'} onClick={() => onRsvp(event)}>{registered ? '✓ Going' : 'RSVP now'} <span>↗</span></button>}</div></div></article>;
}

function DirectoryScreen({ people, query, setQuery }) {
    const filtered = useMemo(() => people.filter((person) => `${person.name} ${person.current_company} ${person.batch_year} ${person.location}`.toLowerCase().includes(query.toLowerCase())), [people, query]);
    return <><div className="screen-heading"><div><span className="section-kicker">THE COMMUNITY</span><h2>Find your people</h2><p>Browse alumni by name, batch, workplace, or city.</p></div><label className="search"><span>⌕</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search people" /></label></div><div className="alumni-grid directory-grid">{filtered.map((person) => <article className="alumni-card" key={person.id || person.name}><div className="avatar avatar-large teal">{initials(person.name)}</div><h3>{person.name}</h3><p>{person.job_title || 'Alumni member'}{person.current_company ? <> at <strong>{person.current_company}</strong></> : null}</p><div className="person-meta"><span>Class of {person.batch_year || '—'}</span><span>{person.location || 'India'}</span></div><button className="connect-button">View profile ↗</button></article>)}</div>{!filtered.length && <div className="empty-state">No alumni match your search.</div>}</>;
}

function EventsScreen({ events, registered, onRsvp, onDelete, admin }) {
    return <><div className="screen-heading"><div><span className="section-kicker">MARK YOUR CALENDAR</span><h2>Community events</h2><p>Join reunions, conversations, and gatherings hosted by your community.</p></div>{admin && <span className="admin-badge">ADMIN MODE</span>}</div><div className="events-grid events-list">{events.map((event) => <EventCard key={event.id} event={event} registered={registered.includes(event.id)} onRsvp={onRsvp} onDelete={onDelete} admin={admin} />)}</div>{!events.length && <div className="empty-state">No events have been published yet.</div>}</>;
}

function ProfileScreen({ user, onSave }) {
    const [form, setForm] = useState({ name: user.name || '', batch_year: user.batch_year || '', current_company: user.current_company || '', job_title: user.job_title || '', location: user.location || '', bio: user.bio || '' });
    const [saved, setSaved] = useState(false);
    async function submit(event) { event.preventDefault(); await onSave({ ...form, batch_year: form.batch_year ? Number(form.batch_year) : undefined }); setSaved(true); }
    return <div className="profile-screen"><div className="screen-heading"><div><span className="section-kicker">YOUR STORY</span><h2>My profile</h2><p>Keep your details current so classmates can find you.</p></div><div className="avatar avatar-profile">{initials(form.name)}</div></div><form className="profile-form" onSubmit={submit}><label>Full name<input value={form.name} onChange={(event) => setForm({ ...form, name: event.target.value })} required /></label><label>Batch year<input type="number" value={form.batch_year} onChange={(event) => setForm({ ...form, batch_year: event.target.value })} /></label><label>Current company<input value={form.current_company} onChange={(event) => setForm({ ...form, current_company: event.target.value })} /></label><label>Job title<input value={form.job_title} onChange={(event) => setForm({ ...form, job_title: event.target.value })} /></label><label>Location<input value={form.location} onChange={(event) => setForm({ ...form, location: event.target.value })} /></label><label className="wide-field">Bio<textarea value={form.bio} onChange={(event) => setForm({ ...form, bio: event.target.value })} rows="4" /></label><div className="form-footer"><button className="primary-button">Save profile</button>{saved && <span className="saved-note">Profile updated</span>}</div></form></div>;
}

function AdminScreen({ events, people, onCreateEvent, onDeleteEvent, onDeletePerson }) {
    const [event, setEvent] = useState({ title: '', description: '', date: '', location: '', capacity: 50 });
    async function submit(eventObject) { eventObject.preventDefault(); await onCreateEvent({ ...event, date: new Date(event.date).toISOString(), capacity: Number(event.capacity) }); setEvent({ title: '', description: '', date: '', location: '', capacity: 50 }); }
    return <><div className="screen-heading"><div><span className="section-kicker">CONTROL ROOM</span><h2>Admin console</h2><p>Manage published events and community profiles.</p></div><span className="admin-badge">{people.length} PEOPLE · {events.length} EVENTS</span></div><div className="admin-layout"><form className="admin-form" onSubmit={submit}><h3>Create an event</h3><label>Title<input required value={event.title} onChange={(e) => setEvent({ ...event, title: e.target.value })} /></label><label>Description<textarea required value={event.description} onChange={(e) => setEvent({ ...event, description: e.target.value })} /></label><label>Date and time<input required type="datetime-local" value={event.date} onChange={(e) => setEvent({ ...event, date: e.target.value })} /></label><label>Location<input required value={event.location} onChange={(e) => setEvent({ ...event, location: e.target.value })} /></label><label>Capacity<input required type="number" min="1" value={event.capacity} onChange={(e) => setEvent({ ...event, capacity: e.target.value })} /></label><button className="primary-button">Publish event ↗</button></form><div><div className="admin-events"><h3>Published events</h3>{events.map((item) => <div className="admin-row" key={item.id}><span><strong>{item.title}</strong><small>{item.location}</small></span><button className="danger-icon" onClick={() => onDeleteEvent(item.id)} aria-label={`Delete ${item.title}`}>×</button></div>)}</div><div className="admin-events admin-people"><h3>People directory</h3>{people.map((item) => <div className="admin-row" key={item.id}><span><strong>{item.name}</strong><small>Class of {item.batch_year || '—'} · {item.current_company || 'No company'}</small></span><button className="danger-icon" onClick={() => onDeletePerson(item.user_id || item.id)} aria-label={`Remove ${item.name}`}>×</button></div>)}</div></div></div></>;
}

function Overview({ events, people, registered, onRsvp, setActive }) {
    return <><div className="welcome-band"><div><span className="welcome-label">THE HALLWAY</span><h2>Stay close to<br /><em>where you began.</em></h2><p>Reconnect with the people and moments that made your school years special.</p><button className="primary-button" onClick={() => setActive('Alumni directory')}>Explore the community <span>↗</span></button></div><div className="sun-art"><span>✦</span><div className="sun" /><div className="arch arch-one" /><div className="arch arch-two" /></div></div><div className="stats"><div><span className="stat-label">COMMUNITY MEMBERS</span><strong>{people.length}</strong><small className="positive">Live directory</small></div><div><span className="stat-label">UPCOMING EVENTS</span><strong>{events.length.toString().padStart(2, '0')}</strong><small>From MongoDB</small></div><div><span className="stat-label">YOUR RSVPS</span><strong>{registered.length}</strong><small className="positive">Persistent</small></div></div><div className="section-heading"><div><span className="section-kicker">MARK YOUR CALENDAR</span><h2>Upcoming events</h2></div><button className="text-button" onClick={() => setActive('Events')}>View all events ↗</button></div><div className="events-grid">{events.slice(0, 3).map((event) => <EventCard key={event.id} event={event} registered={registered.includes(event.id)} onRsvp={onRsvp} />)}</div></>;
}

export default function Home() {
    const [active, setActive] = useState('Overview');
    const [query, setQuery] = useState('');
    const [people, setPeople] = useState([]);
    const [events, setEvents] = useState([]);
    const [registered, setRegistered] = useState([]);
    const [user, setUser] = useState({ name: 'Member' });
    const [loading, setLoading] = useState(true);

    useEffect(() => { (async () => { try { let profile; try { profile = await apiRequest('/auth/profile/'); } catch { await refreshSession(); profile = await apiRequest('/auth/profile/'); } setUser(profile); const [peopleData, eventsData, mine] = await Promise.all([getAlumni(), getEvents(), apiRequest('/my-events/')]); setPeople(peopleData.results.filter((item) => item.role !== 'super_admin')); setEvents(eventsData.results); setRegistered(mine.results.filter((item) => item.status === 'registered').map((item) => item.event_id)); } catch { window.location.assign('/login'); } finally { setLoading(false); } })(); }, []);

    async function saveProfile(profile) { const saved = await updateProfile(profile); setUser(saved); }
    async function registerFor(event) { try { await rsvp(event.id); setRegistered((current) => [...current, event.id]); } catch (error) { if (error.message.includes('Authentication')) window.location.assign('/login'); } }
    async function createEvent(event) { const created = await adminEvents(event); setEvents((current) => [created, ...current]); }
    async function removeEvent(id) { await deleteEvent(id); setEvents((current) => current.filter((event) => event.id !== id)); }
    async function removePerson(id) { await deletePerson(id); setPeople((current) => current.filter((person) => person.id !== id)); }
    const admin = user.role === 'admin' || user.role === 'super_admin';
    const navTabs = admin ? [...tabs, ['Admin console', '◆']] : tabs;
    const title = active === 'Overview' ? `Good morning, ${user.name?.split(' ')[0] || 'there'}` : active;

    return <main className="shell"><aside className="sidebar"><div className="brand"><span className="brand-mark">AM</span><span>Alumni<br /><strong>Meet</strong></span></div><p className="eyebrow">YOUR COMMUNITY</p><nav>{navTabs.map(([item, icon]) => <button key={item} className={active === item ? 'nav-item active' : 'nav-item'} onClick={() => setActive(item)}><span className="nav-icon">{icon}</span>{item}</button>)}</nav><div className="sidebar-bottom"><div className="profile-mini"><span className="avatar avatar-small">{initials(user.name)}</span><span><strong>{user.name}</strong><small>{admin ? 'Administrator' : `Class of ${user.batch_year || '—'}`}</small></span></div><button className="sign-out" onClick={async () => { await logout(); window.location.assign('/login'); }}>↪ Sign out</button></div></aside><section className="content"><header className="topbar"><div><p className="kicker">WEDNESDAY, 26 AUGUST 2026</p><h1>{title}</h1></div><div className="top-actions"><span className="role-pill">{admin ? 'ADMIN' : 'MEMBER'}</span><span className="avatar avatar-small">{initials(user.name)}</span></div></header>{active === 'Overview' && <Overview events={events} people={people} registered={registered} onRsvp={registerFor} setActive={setActive} />}{active === 'Events' && <EventsScreen events={events} registered={registered} onRsvp={registerFor} />}{active === 'Alumni directory' && <DirectoryScreen people={people} query={query} setQuery={setQuery} />}{active === 'My profile' && <ProfileScreen user={user} onSave={saveProfile} />}{active === 'Admin console' && admin && <AdminScreen events={events} people={people} onCreateEvent={createEvent} onDeleteEvent={removeEvent} onDeletePerson={removePerson} />}{loading && <p className="loading-state">Syncing with the community...</p>}</section></main>;
}
